// Hämta kommentarer
const comments = $input.first().json.data || [];

// FILTRERA BORT TOMMA KOMMENTARER
const validComments = comments.filter(c => c.message && c.message.trim().length > 0);

if (validComments.length === 0) {
  return [];
}

// Sortera efter datum (nyast först)
const sorted = validComments.sort((a, b) => 
  new Date(b.created_time) - new Date(a.created_time)
);

const latest = sorted[0];

return [{
  json: {
    commentId: latest.id,
    commentMessage: latest.message,
    commentTime: latest.created_time,
    fromName: latest.from?.name || 'Kund'
  }
}];

// Kolla om kommentaren redan finns i databasen
const results = $input.first().json.results || [];
const commentData = $('3. Extrahera Senaste').first().json;

// Om results är tom = ny kommentar, fortsätt
// Om results har data = redan besvarad, stoppa
if (results.length > 0) {
  return []; // Stoppa - redan besvarad
}

// Ny kommentar - fortsätt
return [{
  json: {
    commentId: commentData.commentId,
    commentMessage: commentData.commentMessage,
    commentTime: commentData.commentTime,
    fromName: commentData.fromName,
    isNew: true
  }
}];

// Hämta kommentar-info från tidigare steg
const commentData = $('5. Ny Kommentar?').first().json;

// Hämta knowledge base
const kbItems = $input.all().map(item => {
  const props = item.json.properties || {};
  let name = '';
  let desc = '';
  let price = '';

  // Extrahera värden från Notion-properties
  for (const [key, val] of Object.entries(props)) {
    if (val.title && val.title[0]) {
      name = val.title[0].plain_text || '';
    }
    if (val.rich_text && val.rich_text[0]) {
      const keyLower = key.toLowerCase();
      if (keyLower.includes('desc') || keyLower.includes('beskrivning')) {
        desc = val.rich_text[0].plain_text || '';
      }
      if (keyLower.includes('price') || keyLower.includes('pris')) {
        price = val.rich_text[0].plain_text || '';
      }
    }
  }

  if (name) {
    return `${name}: ${desc} (${price})`;
  }
  return '';
}).filter(x => x.length > 3);

const knowledgeContext = kbItems.length > 0 
  ? kbItems.join('\n') 
  : 'Probiotika 3-i-1: 1 miljard CFU probiotika, prebiotika, naturliga fibrer. 359 kr.\nCalm & Relax: Naturliga lugnande ingredienser, verkar inom 30-60 min. 359 kr.\nHip & Joint: Stöd för leder, brosk och seniorhundar. 359 kr.';

return [{
  json: {
    commentId: commentData.commentId,
    commentMessage: commentData.commentMessage,
    knowledgeContext: knowledgeContext
  }
}];
